if(window.Chart){Chart.defaults.animation=false;Chart.defaults.font.family="'DM Sans',Arial,sans-serif";}
let chart; const app=document.getElementById('app');
const demoSimulation={materialDelay:0,downtime:0,orderVolume:0,applied:false};
const head=(title,sub,eyebrow='Executive decision centre')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><div class="button-row"><button class="secondary" id="explainView">ⓘ Explain this view</button><button class="secondary" id="dailyBrief">✦ AI Daily Brief</button><button class="primary" id="guidedDemo">▶ Start Guided Demo</button></div></div>`;
const kpi=(t,v,s,cls='')=>`<div class="card kpi" data-page="risk"><div class="kpi-title">${t}<span class="info-dot" data-tooltip="Click to investigate this business metric.">ⓘ</span></div><h2>${v}</h2><div class="sub ${cls}">${s}</div></div>`;
function chartCanvas(id='mainChart'){return `<div class="chart-wrap"><canvas id="${id}"></canvas></div>`}
function makeChart(type='delivery'){let ctx=document.getElementById('mainChart');if(!ctx||!window.Chart)return;chart?.destroy();let labels=['Aug 14','15','16','17','18','19','20','Today','22','23','24','25','26','27','Sep 01'];let map={delivery:{data:D.daily.delivery,label:'On-time delivery %',color:'#0f766e',threshold:90},throughput:{data:D.daily.throughput,label:'Throughput (K units)',color:'#347aab',threshold:94},backlog:{data:D.daily.backlog,label:'Backlog (K units)',color:'#bd7a2b',threshold:90},risk:{data:D.daily.risk,label:'Value at risk ($M)',color:'#bd5353',threshold:1.5}}[type];chart=new Chart(ctx,{type:'line',data:{labels,datasets:[{label:map.label,data:map.data,borderColor:map.color,backgroundColor:map.color+'18',fill:true,tension:.35,pointRadius:(c)=>c.dataIndex===7?4:1,borderWidth:2.5},{label:'Risk threshold',data:Array(15).fill(map.threshold),borderColor:'#d1a146',borderDash:[5,4],pointRadius:0,borderWidth:1.2}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:true,labels:{boxWidth:8,font:{size:10}}},tooltip:{callbacks:{label:c=>`${c.dataset.label}: ${c.raw}`}}},scales:{x:{grid:{display:false},ticks:{font:{size:9}}},y:{grid:{color:'#eef2f2'},ticks:{font:{size:9}}}}}})}
function overview(){app.innerHTML=head('Shahkam AI Decision Centre','Business performance, predictive risk and recommended actions')+`<section class="welcome"><div class="welcome-main"><div class="eyebrow" style="color:#bfe9e3">Start here</div><h2>Welcome — this is the Shahkam AI Decision Intelligence demo</h2><p>An illustrative prototype of how Shahkam’s existing ERP, JACK, barcode and RFID data can move from <b>hindsight to foresight</b> — predicting delivery and production risk early, explaining <i>why</i>, and recommending what to do. It sits <b>alongside</b> your systems; it does not replace the ERP, and it is not connected to live data — every figure here is illustrative.</p><div class="welcome-steps"><div><span>1</span><b>Explore</b><p>Use the left menu to move between business areas.</p></div><div><span>2</span><b>See the maths</b><p>Click any teal “🧮 How is this calculated?” tag — the AI is never a black box.</p></div><div><span>3</span><b>Read the badges</b><p><span class="badge sim">Simulation</span> illustrative · <span class="badge">Live model</span> computed from inputs</p></div></div></div><div class="welcome-path"><div class="label" style="color:#bfe9e3">Suggested 5-minute path</div><a href="#" data-page="overview">1 · Overview — the big picture</a><a href="#" data-page="orders">2 · Orders — can we accept this order?</a><a href="#" data-page="risk">3 · Risk — which orders are in trouble?</a><a href="#" data-page="scenarios">4 · Scenarios — what if we change the plan?</a><a href="#" data-page="roi">5 · Business Value — what is it worth?</a><a href="#" data-page="glossary">New to the terms? · Open the glossary</a><small>Static prototype — sliders and inputs show example states.</small></div></section><section class="attention" style="margin-top:0"><h2>The 5 intelligence modules</h2><p>Each turns your live Oracle / JACK / Barcode / RFID data into a decision. Click to open.</p><div class="launch-grid">${[['orders','▣','Order & Delivery','Feasibility, delivery risk & live order tracking'],['production','◫','Production','Line efficiency & delay prediction from JACK'],['capacity','▦','Capacity & Planning','Order acceptance, optimise & what-if'],['procurement','◇','Procurement','Anomaly detection on transactions'],['management','✦','Management & AI Assistant','Ask the business in plain language']].map((m,i)=>`<button class="card launch-card" data-page="${m[0]}"><span class="lc-num">0${i+1}</span><div class="lc-ico">${m[1]}</div><b>${m[2]}</b><p>${m[3]}</p></button>`).join('')}</div></section><div class="kpi-grid">${kpi('On-Time Delivery','91.4%','↓ 2.1% · forecast <b>87.8%</b>','down')}${kpi('Orders at Risk','24','11 high risk','down')}${kpi('Value at Risk','$1.42M','$980K protected · illustrative','down')}${kpi('Predicted Delays','7 lines','L-07 needs attention','down')}</div><div class="grid-2"><div class="card panel"><div class="panel-head"><div><h3>Business Outlook</h3><p>Where is the business heading?</p></div><div class="tabs" id="outlookTabs"><button class="active" data-chart="delivery">Delivery</button><button data-chart="throughput">Throughput</button><button data-chart="backlog">Backlog</button><button data-chart="risk">Value at risk</button></div></div>${chartCanvas()}<div class="interpret"><b>AI interpretation</b><br>On-time delivery is forecast to decline over the next 30 days, primarily due to increasing backlog and capacity constraints.</div><div style="margin-top:8px">${howBtn('forecast','How is this forecast made?')}</div></div><div class="card panel"><div class="panel-head"><div><h3>AI Daily Brief</h3><p>Today’s management position</p></div><span class="chip risk-med">ACTION NEEDED</span></div><div class="timeline"><div><time>Today</time><b>Delivery</b> stable but forecast to decline</div><div><time>Risk</time><b>11 high-risk orders</b> need review</div><div><time>Constraint</time><b>Line L-07</b> forecast bottleneck</div><div><time>Opportunity</time><b>$185K</b> procurement opportunity</div></div><button class="secondary" data-page="risk">View Full Analysis</button></div></div><section class="attention"><h2>What Needs Attention Today?</h2><p>Prioritised according to illustrative business impact.</p><div class="alert-grid"><div class="card alert-card critical"><h4>🔴 SO-10482 — High Delivery Risk</h4><p><b>$185K</b> order value exposed · <b>61%</b> on-time probability</p><p>Material availability, production backlog and capacity constraints are compounding risk.</p><div class="actions"><button class="primary" data-page="orders">View Analysis</button><button class="secondary" data-page="scenarios">Run Scenario</button>${howBtn('delivery','How?')}</div></div><div class="card alert-card"><h4>🟠 Line L-07 — Delay Predicted</h4><p><b>14 hours</b> predicted delay · <b>78%</b> probability</p><p>Primary driver: throughput decline and machine downtime.</p><div class="actions"><button class="secondary" data-page="production">Investigate</button></div></div><div class="card alert-card"><h4>🟡 PO-48291 — Unusual Transaction</h4><p><b>87/100</b> anomaly score · <b>$42K</b> potential impact</p><p>This requires investigation; it does not indicate fraud.</p><div class="actions"><button class="secondary" data-page="procurement">Investigate</button></div></div></div></section>`;makeChart();bindCommon();document.querySelectorAll('#outlookTabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('#outlookTabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');makeChart(b.dataset.chart)})}
let feasLast=null;
function feasInputs(){return{quantity:+document.getElementById('feasQty').value,requiredDays:+document.getElementById('feasDays').value,materialPct:+document.getElementById('feasMat').value,history:+document.getElementById('feasHist').value,lineId:document.getElementById('feasLine').value}}
function renderFeas(){const inp=feasInputs(),r=ML.assessNewOrder(inp);feasLast=r;const top=r.drivers.slice(0,4);const rec=r.risk==='LOW'?'Feasible — safe to commit to the required date.':r.risk==='MEDIUM'?'Conditionally feasible — commit only with a mitigation (reallocate capacity, confirm materials, or extend 2–3 days).':'High risk — do not commit to this date without reallocating capacity and securing materials.';document.getElementById('feasResult').innerHTML=`<div class="card panel" style="margin:0"><span class="label">P(on-time delivery)</span>${gaugeWrap('feasGauge',r.probPct,r.risk+' risk')}<p style="text-align:center;font-size:11.5px;color:#43555a;margin:4px 0 0">Completion in <b>${r.context.estDays} days</b> · buffer <b>${r.context.buffer>=0?'+':''}${r.context.buffer}d</b></p><div style="text-align:center;margin-top:8px"><button class="pill-how" id="feasHow">🧮 How is this calculated?</button></div></div><div class="card panel" style="margin:0"><span class="label">Top risk drivers (computed live)</span>${top.map(d=>`<div class="driver-row"><span>${d.label} <b>${d.pct}%</b></span><div class="bar"><i style="width:${Math.min(100,d.pct*2.7)}%;background:${d.contribution<0?'#c0605f':'#0f766e'}"></i></div></div>`).join('')}<div class="interpret"><b>AI recommendation.</b> ${rec}</div><div class="button-row"><button class="primary" data-page="scenarios">Run scenario</button><button class="secondary" id="feasCommit">Record decision</button></div></div>`;drawGauge('feasGauge',r.probPct,riskColor(r.risk));document.getElementById('feasHow').onclick=()=>openHowModal('delivery',feasLast);document.getElementById('feasCommit').onclick=()=>{if(window.Feedback)Feedback.capture({type:'Order commitment',ref:'New order',detail:`${inp.quantity.toLocaleString()} units · ${r.probPct}% on-time`,decision:r.risk==='HIGH'?'Held for mitigation':'Committed'});toast('Decision recorded to the feedback dataset for model learning.')};document.querySelectorAll('#feasResult [data-page]').forEach(b=>b.onclick=()=>render(b.dataset.page))}
function bindFeas(){const upd=()=>{document.getElementById('fq').textContent=(+document.getElementById('feasQty').value).toLocaleString();document.getElementById('fd').textContent=document.getElementById('feasDays').value+' days';document.getElementById('fm').textContent=document.getElementById('feasMat').value+'%';document.getElementById('fh').textContent=document.getElementById('feasHist').value+'%';renderFeas()};['feasQty','feasDays','feasMat','feasHist','feasLine'].forEach(id=>{let e=document.getElementById(id);if(e){e.oninput=upd;e.onchange=upd}});renderFeas()}
function orders(){let f=FLAGSHIP;app.innerHTML=head('Order Feasibility & Delivery Prediction','Can Shahkam accept this order and confidently meet the customer’s delivery commitment?','Order intelligence')+`<div class="card panel"><div class="panel-head"><div><h3>New-Order Feasibility — assess before you commit</h3><p>Enter a prospective order. The delivery-risk model scores it <b>live from engineered features</b> — nothing is pre-set.</p></div><span class="badge sim">Live model</span></div><div class="scenario-grid"><div class="control-panel" style="padding:2px"><div class="control"><label>Quantity <b id="fq">25,000</b></label><input type="range" id="feasQty" min="2000" max="60000" step="1000" value="25000"></div><div class="control"><label>Required in <b id="fd">23 days</b></label><input type="range" id="feasDays" min="7" max="60" value="23"></div><div class="control"><label>Material readiness <b id="fm">74%</b></label><input type="range" id="feasMat" min="30" max="100" value="74"></div><div class="control"><label>Similar-order on-time <b id="fh">71%</b></label><input type="range" id="feasHist" min="50" max="99" value="71"></div><div class="control"><label>Assigned line</label><select class="input" id="feasLine">${D.lines.map(l=>`<option ${l.id==='L-07'?'selected':''}>${l.id}</option>`).join('')}</select></div></div><div class="decision-hero" id="feasResult" style="margin:0;grid-template-columns:minmax(240px,1fr) minmax(240px,1.1fr)"></div></div></div>
<div class="card panel"><div class="filters"><input id="orderFilter" placeholder="Search order ID or customer" value="SO-10482"><button class="secondary" id="showOrderTable">Browse all orders</button><span class="notice">Flagship order in production — scored by the same model</span></div><div class="decision-hero"><div class="prediction"><small>AI DELIVERY PREDICTION · SO-10482</small><div class="prob">${f.probPct}%</div><span class="risk-pill">${f.risk} RISK</span><p>Probability of on-time delivery</p><small>Predicted completion <b>21 September</b> · Required <b>18 September</b> · Expected delay <b>${Math.abs(f.context.buffer)} days</b></small><br>${howBtn('delivery','How is this calculated?',true)}</div><div class="card recommend"><span class="label">AI recommendation</span><h3>Do not commit to the current delivery date without operational adjustment.</h3><ol><li>Reallocate capacity from Line L-03</li><li>Prioritise material allocation</li><li>Optimise production sequence</li><li>Run the delivery scenario</li></ol><div class="button-row"><button class="primary" data-page="scenarios">Run Recommended Scenario</button><button class="secondary" id="acceptRisk">Accept Risk</button><button class="secondary" id="escalate">Escalate to Operations</button></div></div></div><div class="grid-2"><div class="card panel"><div class="panel-head"><div><h3>Order make-up — style, colour & size curve</h3><p>Style ${D.orderFocus.style} · ${D.orderFocus.colours.join(' / ')} · 25,000 units</p></div><span class="src-chip">SOURCE · Oracle ERP</span></div>${sizeCurveHTML()}<div class="interpret">The risk is <b>not total quantity</b> — it is concentrated in the <b>L / XL</b> sizes, whose fabric is short.</div></div><div class="card panel"><div class="panel-head"><div><h3>Material / import readiness</h3><p>Why the shortfall exists</p></div><span class="src-chip">Import · LC</span></div><div class="kv"><dt>Source</dt><dd>${D.orderFocus.materialLead.source}</dd><dt>Fabric ETA</dt><dd>${D.orderFocus.materialLead.eta}</dd><dt>Confirmed</dt><dd>18,500 / 25,000</dd></div><div class="interpret">${D.orderFocus.materialLead.note}. The import/LC lead time feeds the <b>material readiness</b> feature directly.</div></div></div><div class="drivers"><div class="card panel"><h3>Why is the order at risk?</h3><p>Contribution of each feature to the risk score (log-odds), computed by the delivery-risk model.</p>${f.drivers.map(d=>`<div class="driver-row"><span>${d.label} <b>${d.pct}%</b></span><div class="bar"><i style="width:${Math.min(100,d.pct*2.7)}%"></i></div></div>`).join('')}<div class="button-row"><button class="secondary" id="evidenceBtn">View Evidence</button>${howBtn('delivery','Show the math')}</div></div><div class="card panel"><h3>Risk profile</h3><p>How strongly each factor pulls the score — at a glance.</p><div class="chart-wrap" style="height:240px"><canvas id="drvRadar"></canvas></div></div></div></div>`;bindCommon();bindFeas();if(typeof drawRadar==='function')drawRadar('drvRadar',f);document.getElementById('evidenceBtn')?.addEventListener('click',evidenceModal);document.getElementById('approvalBtn')?.addEventListener('click',approvalModal);document.getElementById('acceptRisk')?.addEventListener('click',()=>toast('Risk acceptance recorded for management review.'));document.getElementById('escalate')?.addEventListener('click',()=>toast('Escalated to Operations Manager.'));document.getElementById('showOrderTable')?.addEventListener('click',ordersTable)}
function ordersTable(){document.getElementById('modal').innerHTML=`<div class="modal-content"><button class="close">×</button><h2>Orders</h2><div class="table-wrap">${table(D.orders,['id','customer','style','quantity','value','required','line','probability','risk'],['Order ID','Customer','Style','Qty','Value','Required','Line','On-time','Risk'])}</div></div>`;openModal();document.querySelector('.close').onclick=closeModal;document.querySelectorAll('.data-table tbody tr').forEach(r=>r.onclick=()=>{closeModal();render('orders')})}
function table(rows,keys,labels){return `<table class="data-table"><thead><tr>${labels.map((l,i)=>`<th data-sort="${keys[i]}">${l} ↕</th>`).join('')}</tr></thead><tbody>${rows.map(x=>`<tr>${keys.map(k=>`<td>${k==='value'?money(x[k]):k==='price'||k==='expected'?pkr(x[k]):k==='risk'||k==='status'?`<span class="risk-pill ${riskClass(x[k])}">${x[k]}</span>`:x[k]}</td>`).join('')}</tr>`).join('')}</tbody></table>`}
function production(){app.innerHTML=head('Production Intelligence','Target, actual output and early warning signals across 10 production lines','Operations intelligence')+`<div class="kpi-grid">${kpi('Efficiency','87.3%','↓ 3.4% this week','down')}${kpi('Predicted Delays','7 lines','L-07 highest risk','down')}${kpi('Downtime','153 hrs','across 7 lines','down')}${kpi('Throughput','94K','units / week','')}</div><div class="card panel" style="margin-top:14px"><div class="panel-head"><div><h3>Garment critical path — order SO-10482</h3><p>Every stage instrumented: Barcode (cutting), JACK (sewing), RFID (packing) — live into the Oracle DB.</p></div><span class="src-chip jack">JACK · BARCODE · RFID</span></div>${critPathHTML()}</div><div class="grid-2"><div class="card panel"><div class="panel-head"><div><h3>Production forecast</h3><p>Current throughput 94K units/week · forecast 87K</p></div></div>${chartCanvas()}<div class="interpret"><b>AI explanation</b><br>Throughput is expected to decline due to increasing machine downtime and current line constraints.</div></div><div class="card panel"><h3>Line L-07 — delay prediction</h3>${gaugeWrap('prodGauge',78,'delay probability')}<p style="text-align:center;font-size:11.5px;color:#43555a;margin:6px 0">Predicted <b>~14h late</b> · drivers: downtime, throughput decline, DHU.</p><div class="button-row"><button class="primary" data-page="capacity">Redistribute workload</button>${howBtn('production','How is this predicted?')}</div></div></div><div class="card panel" style="margin-top:14px"><div class="panel-head"><div><h3>Line efficiency — live heatmap</h3><p>Efficiency by line across the last 6 shifts (JACK). Green = healthy, red = needs attention.</p></div><span class="src-chip jack">SOURCE · JACK</span></div>${effHeatmap()}<div class="interpret"><b>L-07</b> is running red — 79% efficiency and high DHU (rework) are eroding output — the driver behind its predicted delay.</div></div>`;makeChart('throughput');bindCommon();if(typeof drawGauge==='function')drawGauge('prodGauge',78,'#bd5353')}
function capacity(){let days=['Today','Tomorrow','+2 Days','+3 Days','+4 Days','+5 Days'];let vals=[[83,86,87,90,88,84],[88,90,92,93,90,88],[76,78,80,82,79,77],[91,93,95,94,92,89],[86,85,87,88,86,84],[89,91,92,94,91,89],[94,96,95,94,92,90],[81,82,83,84,85,84],[83,84,86,87,88,86],[89,90,91,92,90,88]];app.innerHTML=head('Capacity Intelligence','See constraints before they become delivery problems','Capacity intelligence')+`<div class="kpi-grid">${kpi('Used Capacity','86.1%','of 1.04M / month')}${kpi('Available Capacity','145K','incl. L-03 opportunity','up')}${kpi('Forecast Utilisation','96.2%','peak in 4 days','down')}${kpi('At-risk Lines','2','L-07, L-04','down')}</div><div class="card panel" style="margin-top:14px"><div class="panel-head"><div><h3>Capacity heatmap</h3><p>Forecast utilisation by production line. Bottlenecks are highlighted.</p></div><span class="notice">Illustrative utilisation</span></div><div class="heatmap"><span></span>${days.map(d=>`<span class="day">${d}</span>`).join('')}${D.lines.map((l,i)=>`<span class="line-name">${l.id}</span>${vals[i].map(v=>`<button class="heat h${v>=95?5:v>=91?4:v>=87?3:v>=82?2:1}" title="View ${l.id} production detail" data-page="production">${v}%</button>`).join('')}`).join('')}</div></div><div class="grid-2"><div class="card panel"><div class="panel-head"><div><h3>Order-acceptance optimiser</h3><p>Can we take on extra units? The solver allocates them within capacity + overtime constraints.</p></div><span class="badge sim">Optimiser</span></div><div class="control"><label>Extra units to place <b id="optVal">5,000</b></label><input type="range" id="optUnits" min="1000" max="30000" step="1000" value="5000"></div><div class="control"><label>Overtime budget <b id="otVal">8 hrs</b></label><input type="range" id="optOt" min="0" max="24" value="8"></div><div id="optResult"></div><div class="button-row">${howBtn('capacity','How is this optimised?')}<button class="secondary" data-page="scenarios">Run Detailed Scenario</button></div></div><div class="card panel"><h3>Constraint watchlist</h3><div class="timeline"><div><time>L-07</time>96% forecast utilisation · 14h predicted delay</div><div><time>L-04</time>94% forecast utilisation · elevated backlog</div><div><time>L-03</time>77% forecast utilisation · reallocation opportunity</div></div></div></div>`;bindCommon();bindCapacityOpt()}
function bindCapacityOpt(){let el=document.getElementById('optUnits');if(!el)return;let upd=()=>{let u=+document.getElementById('optUnits').value,ot=+document.getElementById('optOt').value;document.getElementById('optVal').textContent=u.toLocaleString();document.getElementById('otVal').textContent=ot+' hrs';let c=ML.optimiseCapacity(u,{overtimeHrs:ot});document.getElementById('optResult').innerHTML=`${gaugeWrap('capGauge',c.projOnTime,'proj. on-time')}<div class="metric-list" style="grid-template-columns:repeat(3,1fr);margin:6px 0 4px"><div><span class="label">Feasible</span><h2 class="${c.feasible?'up':'down'}">${c.feasible?'Yes':'No'}</h2></div><div><span class="label">Projected on-time</span><h2 class="${c.projOnTime>=85?'':'down'}">${c.projOnTime}%</h2></div><div><span class="label">Units placed</span><h2>${(c.placed/1000).toFixed(0)}K</h2></div></div>${c.plan.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Line</th><th>From</th><th>+ Units</th><th>To</th></tr></thead><tbody>${c.plan.map(p=>`<tr><td>${p.id}</td><td>${p.fromUtil}%</td><td>+${p.addUnits.toLocaleString()}</td><td>${p.toUtil}%</td></tr>`).join('')}</tbody></table></div>`:''}<div class="interpret"><b>Binding constraint:</b> ${c.binding}. ${c.feasible?'The order can be absorbed within capacity.':'Capacity is exceeded — reject, split, or extend the required date.'}</div>`;drawGauge('capGauge',c.projOnTime,c.projOnTime>=85?'#287453':c.projOnTime>=75?'#c07a1e':'#bd5353')};['optUnits','optOt'].forEach(id=>document.getElementById(id).oninput=upd);upd()}
function procurement(){app.innerHTML=head('Procurement Intelligence','Detect unusual transactions and savings opportunities before action is taken','Procurement intelligence')+`<div class="kpi-grid">${kpi('Transactions Analysed','110','this month')}${kpi('Anomalies Detected','18','need review','down')}${kpi('High-Risk','4','prioritised','down')}${kpi('Savings Opportunity','$185K','annualised · illustrative','up')}</div><div class="card panel" style="margin-top:14px"><div class="panel-head"><div><h3>Transactions requiring review</h3><p>An anomaly does not mean fraud. It indicates a transaction is unusual and should be investigated.</p></div><div class="filters"><select id="procFilter"><option>All statuses</option><option>HIGH</option><option>REVIEW</option></select></div></div><div class="table-wrap">${table(D.procurement.slice(0,6),['po','supplier','material','price','variance','anomaly','status'],['PO Number','Supplier','Material','Unit Price','Variance','Score','Status'])}</div></div>`;bindCommon();document.querySelectorAll('.data-table tbody tr').forEach((r,i)=>r.onclick=()=>procModal(D.procurement[i]));document.getElementById('procFilter').onchange=e=>toast(`Filtered to ${e.target.value}.`) }
function makeForecastChart(type='delivery',canvasId='mainChart'){let ctx=document.getElementById(canvasId);if(!ctx||!window.Chart)return;Chart.getChart(ctx)?.destroy();let series=D.daily[type],f=ML.forecast(series,8),meta={delivery:['On-time %','#0f766e'],throughput:['Throughput K','#347aab'],backlog:['Backlog K','#bd7a2b'],risk:['Value at risk $M','#bd5353']}[type];let hist=series.map((_,i)=>'d'+(i+1)),fut=f.future.map((_,i)=>'+'+(i+1)),labels=[...hist,...fut],pad=series.map(()=>null);let mp=document.getElementById('fmape');if(mp)mp.textContent=f.mape+'%';let fl=document.getElementById('flevel');if(fl)fl.textContent=type==='delivery'?f.future[f.future.length-1]+'%':f.future[f.future.length-1];let fc=new Chart(ctx,{type:'line',data:{labels,datasets:[{label:'Upper 95%',data:[...pad,...f.upper],borderColor:'#9ecfc9',pointRadius:0,borderWidth:1},{label:'Lower 95%',data:[...pad,...f.lower],borderColor:'#9ecfc9',pointRadius:0,borderWidth:1,fill:'-1',backgroundColor:meta[1]+'22'},{label:'Actual',data:[...series,...fut.map(()=>null)],borderColor:'#134f4c',backgroundColor:meta[1]+'12',pointRadius:1,borderWidth:2.5,tension:.3},{label:'Forecast',data:[...pad.slice(0,-1),series[series.length-1],...f.future],borderColor:meta[1],borderDash:[6,4],pointRadius:1,borderWidth:2.5,tension:.3}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:true,labels:{boxWidth:8,font:{size:9},filter:i=>!/95%/.test(i.text)||i.text==='Lower 95%'}},tooltip:{callbacks:{label:c=>`${c.dataset.label}: ${c.raw}`}}},scales:{x:{grid:{display:false},ticks:{font:{size:9}}},y:{grid:{color:'#eef2f2'},ticks:{font:{size:9}}}}}})}
function forecast(){app.innerHTML=head('Forecast Centre','Historical performance, current position and forecasts with 95% confidence intervals','Forward-looking intelligence')+`<div class="card panel"><div class="panel-head"><div><h3>Delivery forecast</h3><p>Holt linear-trend model with weekly seasonality — the shaded band is the 95% confidence interval.</p></div><div class="tabs" id="forecastTabs"><button class="active" data-chart="delivery">Orders</button><button data-chart="throughput">Production</button><button data-chart="backlog">Capacity</button><button data-chart="risk">Business value</button></div></div>${chartCanvas()}<div class="interpret"><b>Forecast explanation.</b> The band widens with the horizon (±1.96·σ·√h), so management sees the realistic range of outcomes — not a single false-precision line.</div><div class="button-row"><span class="mchip">Back-test MAPE <b id="fmape">4.2%</b></span><span class="mchip">30-day point <b id="flevel">—</b></span>${howBtn('forecast','How is this forecast made?')}</div></div><div class="metric-list" style="margin-top:14px"><div class="card"><span class="label">Delivery</span><h2>87.8%</h2><p>Forecast on-time delivery</p></div><div class="card"><span class="label">Throughput</span><h2>87K</h2><p>Forecast weekly units</p></div><div class="card"><span class="label">Value at risk</span><h2>$2.04M</h2><p>Projected illustrative exposure</p></div></div>`;makeForecastChart();bindCommon();document.querySelectorAll('#forecastTabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('#forecastTabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');makeForecastChart(b.dataset.chart)})}
function risk(){let risky=D.orders.filter(o=>o.risk==='HIGH');app.innerHTML=head('Risk Centre','Prioritised signals, evidence and recommended actions','Business risk')+`<div class="card panel"><div class="panel-head"><div><h3>Orders most likely to miss delivery</h3><p>11 high-risk orders represent approximately $740K in illustrative order value.</p></div><button class="primary" data-page="advisor">Ask AI for analysis</button></div>${table(risky,['id','customer','value','required','predicted','line','probability','risk'],['Order','Customer','Value','Required','Predicted','Line','On-time','Risk'])}</div><div class="grid-2"><div class="card panel"><h3>Root Cause Analysis — SO-10482</h3><div class="decision-flow">${['Material Delay','Production Backlog','Capacity Constraint','Reduced Throughput','Predicted Delivery Delay'].map((x,i)=>`<button class="flow-step" data-rca="${i}">${x}</button>${i<4?'<span class="arrow">↓</span>':''}`).join('')}</div><p>Click a factor to trace its evidence. Each provides evidence to support—not replace—management judgment.</p><div id="rcaDetail"></div></div><div class="card panel"><h3>Risk portfolio</h3><div class="driver-row"><span>Capacity constraints <b>42%</b></span><div class="bar"><i style="width:90%"></i></div></div><div class="driver-row"><span>Material availability <b>31%</b></span><div class="bar"><i style="width:67%"></i></div></div><div class="driver-row"><span>Throughput <b>18%</b></span><div class="bar"><i style="width:40%"></i></div></div></div></div>`;bindCommon();let rca=[['Material Delay','6,500 of 25,000 units short; shortfall material expected 12 Sep — 5 days into the production window.','ERP · Material'],['Production Backlog','L-07 carries 82,000 units of backlog vs a ~9,800/day run rate — ~7 days of queue ahead of this order.','JACK · Backlog'],['Capacity Constraint','L-07 forecast utilisation 96% with only 4% headroom; no slack to absorb the order.','JACK · Capacity'],['Reduced Throughput','L-07 throughput trending down with 42h recent downtime, lowering effective output.','JACK · Throughput'],['Predicted Delivery Delay','Compounded effect → 61% on-time, projected completion 21 Sep vs 18 Sep required (−3 days).','Delivery model']];document.querySelectorAll('[data-rca]').forEach(b=>b.onclick=()=>{let r=rca[+b.dataset.rca];document.querySelectorAll('[data-rca]').forEach(x=>x.style.background='');b.style.background='#e8f4f2';document.getElementById('rcaDetail').innerHTML=`<div class="interpret"><b>${r[0]}</b> <span class="badge">${r[2]}</span><br>${r[1]}</div>`})}
function dataPage(){let ints=[['Oracle ERP (OAF · 11g → APEX 26.1 / 26ai)','Orders, styles, materials, import-LC, procurement, finance — single source of truth'],['JACK — sewing','Real-time machine-level output, line efficiency, operator & hourly production'],['Barcode — cutting / fabrication','Bundle-level tracking through cutting and fabrication'],['RFID — packing / warehouse','Automatic finished-goods capture into warehouse & export'],['Executive Dashboard (BI)','Existing production / revenue / planning views — we extend, not replace'],['AI Work-Order Assistant','Shahkam’s in-flight assistant — we complement it, not duplicate it']];
let entities=['Order','Customer','Style / Product','Material','Production Run','Machine (JACK)','Capacity','Fulfilment (RFID)'];
let features=[['material_readiness','Confirmed material ÷ required by start date','Oracle ERP','Delivery risk'],['backlog_pressure','Queued units ÷ order size','JACK + ERP','Delivery risk'],['capacity_headroom','1 − line utilisation','JACK','Delivery · Capacity'],['schedule_buffer','Projected completion vs required date','ERP + Planning','Delivery risk'],['historical_ontime','On-time rate of similar orders','Oracle ERP','Delivery risk'],['throughput_trend','7-day throughput slope','JACK','Forecast'],['price_zscore','Std-devs from supplier average price','ERP Procurement','Anomaly'],['quantity_zscore','Std-devs from normal order quantity','ERP Procurement','Anomaly']];
app.innerHTML=head('Data & Integrations','Approved sources on Shahkam’s on-premises Oracle stack — the canonical model, feature layer and lineage','Technical foundation')+`<div class="onprem-banner"><div class="ob-ico">◆</div><div><b>On-premises · Oracle-native.</b> Everything runs inside Shahkam’s own data centre (Dell PowerEdge R740 / R750 / R940). Models execute as <b>in-database Oracle Machine Learning</b> on <b>Oracle 26ai</b>; RAG uses <b>26ai AI Vector Search</b>. <small>No operational data leaves the building — no public cloud.</small></div></div><div class="integration-grid">${ints.map(x=>`<div class="card integration"><span class="chip risk-low">CONNECTED</span><h4>${x[0]}</h4><p>Provides: ${x[1]}</p></div>`).join('')}</div>
<div class="card panel" style="margin-top:14px"><h3>Data lineage</h3><p>Systems of record are never queried by the model directly — data flows through governed, versioned stages.</p><div class="pipeline" style="margin-top:10px">${[['Systems of record','Oracle ERP · JACK · Barcode · RFID'],['Ingest & validate','Standardise, reconcile keys & timestamps'],['Canonical model','One entity model for orders → fulfilment'],['Feature layer','Versioned, reproducible ML features'],['Inference API','Models consume approved features only']].map((s,i,a)=>`<div class="pipe-step"><div class="n">${i+1}</div><b>${s[0]}</b><p>${s[1]}</p></div>${i<a.length-1?'<span class="pipe-arrow">→</span>':''}`).join('')}</div></div>
<div class="grid-2"><div class="card panel"><h3>Canonical entity model</h3><p>Business keys reconciled across systems into one analytical model.</p><div class="arch-row" style="margin-top:10px">${entities.map(e=>`<div class="arch-box">${e}</div>`).join('')}</div></div>
<div class="card panel"><h3>Data quality</h3><h2>94.7%</h2>${[['Completeness',97],['Consistency',94],['Freshness',96],['Reconciliation',92]].map(x=>`<div class="driver-row"><span>${x[0]} <b>${x[1]}%</b></span><div class="bar"><i style="width:${x[1]}%"></i></div></div>`).join('')}<p style="font-size:11px;color:#8a9a9a;margin-top:8px">Issues gated before modelling: missing timestamps, duplicate order IDs, incomplete material records.</p></div></div>
<div class="card panel" style="margin-top:14px"><div class="panel-head"><div><h3>Feature layer <span class="badge">${features.length} features · v3</span></h3><p>Engineered, versioned predictive signals — the same features power the models and the “How is this calculated?” views.</p></div><span class="badge sim">Versioned</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Feature</th><th>Definition</th><th>Source</th><th>Used by</th></tr></thead><tbody>${features.map(f=>`<tr><td class="num">${f[0]}</td><td>${f[1]}</td><td>${f[2]}</td><td>${f[3]}</td></tr>`).join('')}</tbody></table></div></div>
<div class="card panel" style="margin-top:14px"><div class="panel-head"><div><h3>Native capability map — runs inside Oracle</h3><p>Each AI capability maps to an Oracle-native equivalent that executes where the data already lives — on-prem, nothing leaves the DB.</p></div><span class="badge">Oracle 26ai · APEX 26.1</span></div><div class="table-wrap"><table class="fitmap"><thead><tr><th>Capability</th><th>Approach shown</th><th>Oracle-native equivalent</th><th>Runs</th></tr></thead><tbody>${(typeof FIT_MAP!=='undefined'?FIT_MAP:[]).map(r=>`<tr><td><b>${r[0]}</b></td><td>${r[1]}</td><td class="ora">${r[2]}</td><td><span class="chip risk-low">${r[3]}</span></td></tr>`).join('')}</tbody></table></div></div>
<div class="card panel" style="margin-top:14px"><h3>Reference architecture — on-premises, Oracle-native</h3><p>Existing Oracle systems stay the record; this layer adds the intelligence, entirely in-house.</p><div class="architecture" style="padding:16px 0 4px"><div class="arch-row">${['Oracle ERP (OAF/11g → APEX 26.1)','JACK · sewing','Barcode · cutting','RFID · packing','Exec Dashboard','Work-Order Assistant'].map(x=>`<div class="arch-box">${x}</div>`).join('')}</div><div class="arch-arrow">↓</div><div class="arch-box strong">Canonical Data Foundation · Feature Layer — inside Oracle 26ai</div><div class="arch-arrow">↓</div><div class="arch-row">${['Oracle ML · GLM','OML · ESM Forecast','OML · Anomaly','APEX / PLSQL Optimiser'].map(x=>`<div class="arch-box strong">${x}</div>`).join('')}</div><div class="arch-arrow">↓</div><div class="arch-box strong">26ai AI Vector Search (RAG) · Select AI / APEX AI → private on-prem LLM</div><div class="arch-arrow">↓</div><div class="arch-row">${['APEX Dashboards','Alerts','AI Advisor','Scenarios'].map(x=>`<div class="arch-box">${x}</div>`).join('')}</div><div class="arch-arrow">↓</div><div class="arch-box strong">Human Decision · advisory, human-in-the-loop</div></div></div>`;bindCommon()}
function governance(){app.innerHTML=head('AI Governance','Human oversight, access control and traceability for AI-assisted decisions','Governance')+`<div class="grid-2"><div class="card panel"><h3>Human approval required</h3><p>AI recommendations are advisory. Consequential operational decisions remain under authorised management control.</p><div class="button-row"><button class="primary" id="governanceApprove">Approve demonstration recommendation</button><button class="secondary" data-page="advisor">Request More Analysis</button></div><div class="interpret"><b>AI cannot directly modify ERP data.</b><br>Analytical services provide evidence and recommendations for human decision.</div></div><div class="card panel"><h3>Authorised roles</h3>${['Executive','Operations Manager','Production User','Procurement User','Finance / Commercial','IT / Data Administrator','AI / Model Administrator'].map(x=>`<div class="statline"><span>${x}</span><span class="chip risk-low">Role-based access</span></div>`).join('')}</div></div><div class="card panel" style="margin-top:14px"><div class="panel-head"><div><h3>AI tool authorisation (allow-list)</h3><p>The AI agent may call only these approved, read-only tools. It cannot query ERP tables directly or execute transactions — a control against prompt-injection and unsafe tool use.</p></div><span class="chip risk-low">ENFORCED</span></div><div class="integration-grid">${[['delivery_risk_model.predict','Read','Approved'],['production.delay_model','Read','Approved'],['optimise_capacity','Read','Approved'],['anomaly_model.score','Read','Approved'],['rag_search','Read','Approved'],['query_delivery_ledger','Read','Approved'],['write_to_erp','Write','Blocked'],['execute_payment','Write','Blocked']].map(t=>`<div class="card integration" style="padding:12px"><span class="chip ${t[2]==='Approved'?'risk-low':'risk-high'}">${t[2]==='Approved'?'✓ '+t[1]:'✕ Blocked'}</span><h4 style="font-family:'DM Mono',monospace;font-size:11px;margin:7px 0 2px">${t[0]}</h4></div>`).join('')}</div></div><div class="card panel" style="margin-top:14px"><h3>Audit trail</h3><div class="timeline" id="auditTrail"><div><time>10:42</time>User viewed SO-10482</div><div><time>10:45</time>Scenario B simulated</div><div><time>10:47</time>Recommendation generated</div><div><time>10:49</time>Recommendation submitted for approval</div><div><time>10:52</time>Recommendation approved</div></div></div>`;bindCommon();document.getElementById('governanceApprove').onclick=()=>toast('Decision recorded in audit trail.')}
function architecture(){app.innerHTML=head('Reference Architecture','Oracle-native and on-premises — existing systems stay the record; this layer adds the intelligence','Architecture')+`<div class="onprem-banner"><div class="ob-ico">◆</div><div><b>Runs entirely on-premises, inside Shahkam’s Oracle 26ai + APEX 26.1.</b> The intelligence layer executes as in-database Oracle Machine Learning and 26ai AI Vector Search — <small>no operational data leaves the data centre.</small></div></div><div class="card architecture"><div class="arch-row">${['Oracle ERP (OAF/11g → APEX 26.1)','JACK · sewing','Barcode · cutting','RFID · packing','Exec Dashboard','Work-Order Assistant'].map(x=>`<div class="arch-box">${x}</div>`).join('')}</div><div class="arch-arrow">↓</div><div class="arch-box strong">Data Integration — within Oracle 26ai (no external ETL)</div><div class="arch-arrow">↓</div><div class="arch-box strong">Canonical Data Foundation · Feature Layer (in-database)</div><div class="arch-arrow">↓</div><div class="arch-row">${['Oracle ML · GLM','OML · ESM Forecast','OML · Anomaly','APEX / PLSQL Optimiser'].map(x=>`<div class="arch-box strong">${x}</div>`).join('')}</div><div class="arch-arrow">↓</div><div class="arch-box strong">26ai AI Vector Search (RAG) · Select AI / APEX AI orchestration → private on-prem LLM</div><div class="arch-arrow">↓</div><div class="arch-row">${['APEX Dashboards','Alerts','AI Advisor','Scenarios'].map(x=>`<div class="arch-box">${x}</div>`).join('')}</div><div class="arch-arrow">↓</div><div class="arch-box strong">Human Decision (advisory · human-in-the-loop)</div><p class="notice">Existing Oracle systems = Systems of Record &nbsp;·&nbsp; this AI layer = System of Intelligence &nbsp;·&nbsp; on-prem, data never leaves</p></div>`;bindCommon()}
function glossary(){let concepts=[['Prediction','An estimate of something that hasn’t happened yet — e.g. “will this order be late?”'],['Forecast','A prediction over time, shown with a best-to-worst range instead of a single false-precise number.'],['Feature','One piece of input the model looks at — e.g. how much material is ready.'],['Model','The trained formula that turns features into a prediction.'],['Training','Teaching the model by showing it thousands of past orders with known outcomes.'],['Logistic regression','A simple, fully transparent model that adds up weighted inputs into a probability.'],['Gradient-boosted trees (XGBoost)','A more powerful model that captures complex patterns between inputs.'],['Anomaly detection (Isolation Forest)','Flags transactions that look unusual versus the norm — a prompt to investigate, not an accusation.'],['RAG','Retrieval-Augmented Generation — the AI answers only from your approved documents, and cites them.'],['LLM','Large Language Model — the language engine that understands questions and explains answers in plain English.'],['AI agent / tool-calling','The AI calls approved analytical tools to get real answers instead of guessing.'],['Optimisation','Finding the best plan under real limits — capacity, overtime and material availability.'],['Human-in-the-loop','A person approves any consequential decision; the AI only advises.']];
let measures=[['On-time probability','The chance an order is delivered on or before its due date.'],['Confidence interval','The realistic range around a forecast — we show the 95% band.'],['Risk drivers','The specific factors pushing a prediction up or down, ranked by contribution.'],['ROC-AUC','How well the model separates late from on-time orders — 1.0 is perfect, 0.5 is a coin-flip.'],['MAPE','Average forecast error as a percentage — lower is better.'],['Drift / PSI','A check that today’s data still resembles the data the model learned from; if it drifts too far, we retrain.'],['Retraining','Updating the model as new real outcomes arrive, so it keeps improving.'],['RBAC','Role-based access control — each role sees only what it should.']];
let item=x=>`<div class="gloss-item"><b>${x[0]}</b><span>${x[1]}</span></div>`;
app.innerHTML=head('Glossary & Help','Plain-language explanations of every term used in this demo — no background needed','Understand the demo')+`<div class="plain">💡 <b>The one-line version:</b> this platform turns the data Shahkam already collects into <b>early warnings and clear recommendations</b> — it predicts what’s likely to happen, explains why, suggests what to do, and always leaves the decision to a person.</div><div class="gloss-grid"><div class="card panel gloss-card"><h3>🧠 AI concepts</h3>${concepts.map(item).join('')}</div><div class="card panel gloss-card"><h3>📏 How we measure it</h3>${measures.map(item).join('')}</div></div><div class="card panel" style="margin-top:14px"><h3>How to use this demo</h3><div class="metric-list"><div class="card"><span class="label">Navigate</span><p style="font-size:11.5px;color:var(--muted);margin:6px 0 0">Use the left menu. The <b>Suggested 5-minute path</b> on the Overview page is the quickest tour.</p></div><div class="card"><span class="label">See the maths</span><p style="font-size:11.5px;color:var(--muted);margin:6px 0 0">Click any <b>🧮 How is this calculated?</b> tag to see the exact algorithm, inputs and formula behind a number.</p></div><div class="card"><span class="label">Badges</span><p style="font-size:11.5px;color:var(--muted);margin:6px 0 0"><span class="badge sim">Simulation</span> = illustrative figure · <span class="badge">Live model</span> = computed from inputs · <span class="notice" style="padding:2px 6px">Illustrative</span> = example data, real numbers come from the Proof of Value.</p></div></div></div>`;bindCommon()}
const alertCfg={ontime:75,anomaly:75,delay:6};
function computeAlerts(){let out=[];D.orders.forEach(o=>{if(o.probability<alertCfg.ontime)out.push({sev:o.probability<65?'Critical':'High',icon:o.probability<65?'🔴':'🟠',title:`Delivery risk — ${o.id}`,what:`${o.probability}% on-time probability (threshold ${alertCfg.ontime}%)`,why:`${o.customer} · ${money(o.value)} exposed`,page:'orders'});});D.lines.forEach(l=>{if(l.delay>=alertCfg.delay)out.push({sev:l.delay>=12?'High':'Medium',icon:l.delay>=12?'🟠':'🟡',title:`Production delay — ${l.id}`,what:`${l.delay}h predicted delay (threshold ${alertCfg.delay}h)`,why:`Utilisation ${l.util}% · downtime ${l.downtime}h`,page:'production'});});D.procurement.forEach(p=>{if(p.anomaly>=alertCfg.anomaly)out.push({sev:p.anomaly>=85?'High':'Medium',icon:p.anomaly>=85?'🟠':'🟡',title:`Procurement anomaly — ${p.po}`,what:`Score ${p.anomaly}/100 (threshold ${alertCfg.anomaly})`,why:`${p.supplier} · +${p.variance}% price variance`,page:'procurement'});});let rank={Critical:0,High:1,Medium:2,Low:3};return out.sort((a,b)=>rank[a.sev]-rank[b.sev])}
function alerts(){app.innerHTML=head('Business Alert Centre','Threshold-driven alerts that explain what happened, why it matters and what to do','Alert management')+`<div class="grid-2"><div class="card panel"><div class="panel-head"><div><h3>Alert thresholds</h3><p>Tune sensitivity — the feed recomputes live from operational data.</p></div><span class="badge sim">Configurable</span></div><div class="control"><label>On-time probability below <b id="alOntime">75%</b></label><input type="range" id="alO" min="55" max="90" value="75"></div><div class="control"><label>Anomaly score above <b id="alAnom">75</b></label><input type="range" id="alA" min="50" max="95" value="75"></div><div class="control"><label>Predicted line delay above <b id="alDelay">6h</b></label><input type="range" id="alD" min="2" max="14" value="6"></div><div id="alSummary" class="metric-list" style="grid-template-columns:repeat(3,1fr)"></div></div><div class="card panel"><h3>Notification routing</h3><p>Each alert type routes to the responsible role.</p><div class="timeline"><div><time>Delivery</time>→ Operations Manager · Finance</div><div><time>Production</time>→ Production User · Operations</div><div><time>Procurement</time>→ Procurement User</div><div><time>Capacity</time>→ Operations Manager</div></div><div class="interpret">Alerts are advisory signals with evidence — routed for human action, never auto-executed.</div></div></div><div class="attention" style="margin-top:14px"><div class="panel-head"><h2 style="margin:0">Live alert feed</h2><div class="tabs" id="alTabs"><button class="active" data-alert-filter="All">All</button><button data-alert-filter="Critical">Critical</button><button data-alert-filter="High">High</button><button data-alert-filter="Medium">Medium</button></div></div><div class="alert-grid" id="alFeed"></div></div>`;bindCommon();let flt='All';let refresh=()=>{alertCfg.ontime=+document.getElementById('alO').value;alertCfg.anomaly=+document.getElementById('alA').value;alertCfg.delay=+document.getElementById('alD').value;document.getElementById('alOntime').textContent=alertCfg.ontime+'%';document.getElementById('alAnom').textContent=alertCfg.anomaly;document.getElementById('alDelay').textContent=alertCfg.delay+'h';let all=computeAlerts();document.getElementById('alSummary').innerHTML=`<div><span class="label">Total</span><h2>${all.length}</h2></div><div><span class="label">Critical</span><h2 class="down">${all.filter(a=>a.sev==='Critical').length}</h2></div><div><span class="label">High</span><h2>${all.filter(a=>a.sev==='High').length}</h2></div>`;let list=flt==='All'?all:all.filter(a=>a.sev===flt);document.getElementById('alFeed').innerHTML=list.slice(0,12).map(a=>`<div class="card alert-card ${a.sev==='Critical'?'critical':''}"><h4>${a.icon} ${a.title}</h4><p><b>What:</b> ${a.what}</p><p><b>Why:</b> ${a.why}</p><div class="actions"><button class="secondary" data-page="${a.page}">Investigate</button></div></div>`).join('')||'<p style="color:#8a9a9a;font-size:12px">No alerts above the current thresholds.</p>';document.querySelectorAll('#alFeed [data-page]').forEach(b=>b.onclick=()=>render(b.dataset.page))};['alO','alA','alD'].forEach(id=>document.getElementById(id).oninput=refresh);document.querySelectorAll('#alTabs [data-alert-filter]').forEach(button=>button.onclick=()=>{document.querySelectorAll('#alTabs [data-alert-filter]').forEach(x=>x.classList.remove('active'));button.classList.add('active');flt=button.dataset.alertFilter;refresh()});refresh()}
function procModal(x){let a=ML.anomalyScore({variance:x.variance});let feats=a.feats.map(f=>`<div class="driver-row"><span>${f.label} <b>${f.z>=0?'+':''}${f.z}σ</b></span><div class="bar"><i style="width:${Math.min(100,Math.abs(f.z)*30)}%;background:${f.z>=1.5?'#c0605f':'#0f766e'}"></i></div></div>`).join('');document.getElementById('modal').innerHTML=`<div class="modal-content"><button class="close">×</button><span class="label">PROCUREMENT ANOMALY ANALYSIS</span><h2>${x.po} — Anomaly Score ${x.anomaly} / 100</h2><div class="grid-2"><div><span class="label">Signal breakdown (feature deviations)</span>${feats}</div><div class="card panel"><span class="label">Potential impact</span><h2>${money(42000)}</h2><small>Illustrative demo value</small><div class="kv" style="margin-top:10px"><dt>Supplier</dt><dd>${x.supplier}</dd><dt>Material</dt><dd>${x.material}</dd><dt>Unit price</dt><dd>${pkr(x.price)} vs ${pkr(x.expected)}</dd><dt>Price variance</dt><dd>+${x.variance}%</dd></div></div></div><div class="interpret"><b>An anomaly does not mean fraud.</b> Isolation Forest flags this transaction as statistically unusual (avg. path length ${a.avgPath}) and routes it to a human investigator with the evidence above.</div><div class="button-row"><button class="primary" id="investigate">Investigate</button><button class="secondary" id="markValid">Mark Valid</button>${howBtn('anomaly','How is the score computed?')}<button class="danger" id="escalatePO">Escalate</button></div></div>`;openModal();document.querySelector('.close').onclick=closeModal;document.getElementById('investigate').onclick=()=>{closeModal();if(window.Feedback)Feedback.capture({type:'Procurement review',ref:x.po,detail:`Score ${x.anomaly}`,decision:'Investigating'});toast('Investigation assigned to Procurement.')};document.getElementById('markValid').onclick=()=>{closeModal();if(window.Feedback)Feedback.capture({type:'Procurement review',ref:x.po,detail:`Score ${x.anomaly}`,decision:'Marked valid (false positive)'});toast(`${x.po} marked valid — fed back to reduce false positives.`)};document.getElementById('escalatePO').onclick=()=>{closeModal();render('governance');toast(`${x.po} escalated for management review.`)}}
function evidenceModal(){document.getElementById('modal').innerHTML=`<div class="modal-content"><button class="close">×</button><span class="label">SUPPORTING EVIDENCE</span><h2>SO-10482 — Delivery risk evidence</h2><div class="metric-list"><div class="card"><span class="label">Material</span><h3>18,500 / 25,000</h3><p>Shortfall: 6,500<br>Expected: 12 September</p></div><div class="card"><span class="label">Production</span><h3>82,000 backlog</h3><p>Average: 9,800/day<br>Required: 11,400/day</p></div><div class="card"><span class="label">Similar orders</span><h3>5 of 17 late</h3><p>Average delay: 2.7 days</p></div></div><div class="interpret"><b>Evidence is informative, not determinative.</b><br>Management retains responsibility for operational decisions.</div></div>`;openModal();document.querySelector('.close').onclick=closeModal}
function approvalModal(){document.getElementById('modal').innerHTML=`<div class="modal-content"><button class="close">×</button><span class="label">HUMAN-IN-THE-LOOP</span><h2>Approve recommended scenario?</h2><p>AI recommends reallocating Line L-03 and applying 8 hours of overtime. The simulated on-time probability is <b>91%</b>.</p><div class="interpret"><b>Human approval required</b><br>AI recommendations are advisory. Operational decisions remain under management control.</div><div class="button-row"><button class="primary" id="approveDecision">Approve</button><button class="danger" id="rejectDecision">Reject</button><button class="secondary" id="moreAnalysis">Request More Analysis</button></div></div>`;openModal();document.querySelector('.close').onclick=closeModal;document.getElementById('approveDecision').onclick=()=>{closeModal();toast('Decision Recorded — recommendation approved at 10:40.')};document.getElementById('rejectDecision').onclick=()=>{closeModal();toast('Decision Recorded — recommendation rejected.')};document.getElementById('moreAnalysis').onclick=()=>{closeModal();render('advisor')}}
function guidedDemo(step=0){let slides=[['New Order Detected','SO-10482 · 25,000 units · PKR 52M illustrative value · required 18 September'],['AI Feasibility Assessment','Materials, current commitments, production, capacity and historical performance are evaluated.'],['Risk Detected','61% on-time probability · HIGH RISK'],['AI Explains Why','Material shortage · production backlog · capacity constraint'],['Business Impact','PKR 52M illustrative order value exposed.'],['What-If Simulation','Reallocate Line L-03 and add limited overtime.'],['Result','91% on-time probability · expected completion 17 September'],['AI Recommendation','Proceed with recommended operational changes.'],['Human Approval','Management remains in control and approves.'],['Decision Recorded','Action and outcome are stored for monitoring and learning.']];let x=slides[step];document.getElementById('modal').innerHTML=`<div class="modal-content guided"><button class="close">×</button><div class="step-no">GUIDED DEMO · STEP ${step+1} OF 10</div><h2>${x[0]}</h2><div class="demo-visual">${x[1]}</div><p>From reactive reporting to predictive, explainable and actionable decision-making.</p><div class="button-row" style="justify-content:center">${step?'<button class="secondary" id="prevDemo">Back</button>':''}${step<9?'<button class="primary" id="nextDemo">Continue</button>':'<button class="primary" id="finishDemo">Finish Demo</button>'}</div></div>`;openModal();document.querySelector('.close').onclick=closeModal;document.getElementById('prevDemo')?.addEventListener('click',()=>guidedDemo(step-1));document.getElementById('nextDemo')?.addEventListener('click',()=>guidedDemo(step+1));document.getElementById('finishDemo')?.addEventListener('click',()=>{closeModal();acceptOrder(91)})}
function openModal(){document.getElementById('modal').classList.add('open')}function closeModal(){document.getElementById('modal').classList.remove('open');document.getElementById('modal').innerHTML=''}
function toast(msg){let t=document.createElement('div');t.textContent=msg;t.style.cssText='position:fixed;right:24px;top:75px;background:#164e4b;color:white;padding:11px 15px;border-radius:6px;z-index:50;box-shadow:0 8px 24px #1238;font-size:12px';document.body.append(t);setTimeout(()=>t.remove(),2800)}
const PAGE_HELP={
 overview:['The executive home screen — the business at a glance.','Headline KPIs, an AI daily brief, and the three items needing attention today.','Click any KPI to open the Risk Centre, or follow the 5-minute path in the welcome panel.'],
 orders:['Decide whether a specific order can be delivered on time before committing.','A live feasibility form, plus the flagship order SO-10482 scored at 61% on-time.','Drag the sliders to watch the prediction change, then open “How is this calculated?”.'],
 production:['Early-warning signals across the 10 production lines.','Predicted delays, the L-07 delay prediction, and per-line status.','Open “How is this predicted?” on the L-07 card to see the JACK signals used.'],
 capacity:['Whether new commitments are realistically achievable.','A forecast utilisation heatmap and an interactive order-acceptance optimiser.','Move the “extra units” slider — the solver re-plans and shows the binding constraint.'],
 procurement:['Unusual purchase transactions that deserve a human review.','110 transactions scored for how unusual they are (an anomaly is not fraud).','Click any row to see the feature-by-feature evidence behind its score.'],
 forecast:['Where key metrics are heading over the next 30 days.','Forecasts with a 95% confidence band — a realistic range, not false precision.','Switch the series tabs; open “How is this forecast made?”.'],
 risk:['Orders most likely to miss delivery, with root-cause analysis.','A ranked list plus a clickable root-cause chain for SO-10482.','Click each root-cause step to reveal its supporting evidence.'],
 scenarios:['A what-if simulator for the plan behind SO-10482.','Current plan vs Scenario A vs your own scenario.','Adjust capacity, overtime and materials to reach a safer delivery outcome.'],
 advisor:['A natural-language assistant grounded in the demo data.','A chat with governed tool-calls shown before each grounded answer.','Type a question or click a suggested one — try “Why is SO-10482 at risk?”.'],
 knowledge:['Answers grounded only in Shahkam’s approved documents, with citations.','A retrieval trace and the exact document chunks used for each answer.','Ask a policy question — the answer cites the SOP or policy it came from.'],
 alerts:['Threshold-driven business alerts routed to the right role.','Three sensitivity sliders and a live alert feed that recomputes from data.','Lower a threshold and watch new alerts appear in the feed.'],
 roi:['The business case — how AI spend turns into profit.','Payback, NPV, a profit-bridge waterfall and a sensitivity view.','Adjust the assumption sliders to fit Shahkam’s real numbers.'],
 data:['The governed data foundation beneath every prediction.','Connected sources, data lineage, the canonical model and the feature layer.','Hover the feature-layer rows to see where each signal comes from.'],
 models:['The model registry — algorithms, metrics and monitoring.','Per-model methodology, validation metrics, drift and the training pipeline.','Switch models with the picker; open “Show the live calculation”.'],
 learning:['How human decisions become training data and improve the model.','Labelled examples, drift monitoring and a governed retrain trigger.','Click “Simulate 10 decisions”, then “Trigger governed retrain”.'],
 governance:['Human oversight, access control and traceability.','The human-approval control, the AI tool allow-list, and the audit trail.','Note which tools are Approved (read-only) vs Blocked (write).'],
 architecture:['How the platform sits above the existing systems of record.','The layered flow from source systems to a human decision.','Systems of record stay authoritative; the AI layer is the system of intelligence.'],
 glossary:['Plain-language definitions of every term in the demo.','AI concepts and how-we-measure-it, plus a how-to-use guide.','Use this any time a term on another page is unfamiliar.'],
 ml:['The machine-learning models shown end to end.','Raw Oracle order records → engineered features → the logistic maths → 61%.','Move the live sliders and open “See the exact logistic maths”.'],
 forecasting:['The forecasting technique shown end to end.','Raw daily history → level + trend → a projection with a 95% band.','Switch the series and open “How the forecast is made”.'],
 anomaly:['The anomaly-detection technique shown end to end.','Raw procurement transactions → z-scores → an Isolation-Forest score.','Click any raw transaction to see how its score is built.'],
 optimisation:['The optimisation technique shown end to end.','Raw line capacity → constraints → the best feasible allocation.','Move the “extra units” slider to run the solver live.'],
 fit:['How this solution aligns with Shahkam’s actual Oracle stack and roadmap.','A native-capability map, how it complements your in-flight AI, and the migration sequence.','Check the map: every capability has an on-prem, in-database Oracle equivalent.']
};
function explainView(){let page=document.querySelector('.nav-item.active')?.dataset.page||'overview';let h=PAGE_HELP[page]||['This view.','','']; let title=document.querySelector('.page-head h1')?.textContent||'This page';document.getElementById('modal').innerHTML=`<div class="modal-content"><button class="close">×</button><span class="label">Explain this view</span><h2 style="margin:4px 0 10px">${title}</h2><div class="plain">💡 <b>What this is:</b> ${h[0]}</div><p style="margin:12px 0 4px"><span class="label">What you’re seeing</span></p><p style="font-size:12px;color:#43555a;line-height:1.6;margin:0">${h[1]}</p><p style="margin:14px 0 4px"><span class="label">Try this</span></p><p style="font-size:12px;color:#43555a;line-height:1.6;margin:0">${h[2]}</p><p style="font-size:11px;color:#6a7a7a;margin-top:14px">New to the terms? Open <b>Glossary &amp; Help</b> from the menu.</p></div>`;openModal();document.querySelector('#modal .close').onclick=closeModal;}
function bindCommon(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>render(b.dataset.page));document.getElementById('guidedDemo')?.addEventListener('click',()=>guidedDemo());document.getElementById('dailyBrief')?.addEventListener('click',()=>toast('Daily Brief refreshed with illustrative demo data.'));document.getElementById('explainView')?.addEventListener('click',explainView)}
/* ===================== DECISION-ORIENTED UX (v7) ===================== */
const orderState={accepted:false,prob:61};
function statusTag(level,text){const m={HIGH:['high','🔴','High Risk'],MEDIUM:['med','🟠','Needs Attention'],LOW:['low','🟢','On Track']}[level]||['med','🟠','Needs Attention'];return `<span class="stag ${m[0]}">${m[1]} ${text||m[2]}</span>`}
function dcKpi(t,v,s,cls){return `<div class="card kpi"><div class="kpi-title">${t}</div><h2>${v}</h2><div class="sub ${cls||''}">${s}</div></div>`}
function decisionCard(sev,rank,level,title,big,lbl,reason,improve,cta,page,id){return `<div class="decision-card sev-${sev}"${id?` id="${id}"`:''}><div class="dc-rank">${rank}</div><div class="dc-body"><div class="dc-ttl">${statusTag(level)} ${title}</div><div class="dc-reason"><b>Why:</b> ${reason}</div></div><div class="dc-metric"><div class="dm-big">${big}</div><div class="dm-lbl">${lbl}</div><div class="dm-improve">${improve}</div><button class="primary btn-review" data-page="${page}">${cta} →</button></div></div>`}
function orderStripHTML(){const o=D.orderFocus;const cells=[['Order',o.id],['Customer',o.customer],['Quantity',o.quantity.toLocaleString()+' units'],['Order value',money(o.value)],['Required',o.required],['Stage',orderState.accepted?'In production · Sewing':'Awaiting decision']];return `<div class="order-strip" style="margin-top:14px">${cells.map(c=>`<div><div class="os-l">${c[0]}</div><div class="os-v">${c[1]}</div></div>`).join('')}</div>`}
function verdictHTML(prob,risk,accepted){const low=risk==='LOW';const statusTxt=accepted?'🟢 ACCEPTED · LOW RISK':(risk==='HIGH'?'🔴 ':risk==='MEDIUM'?'🟠 ':'🟢 ')+risk+' DELIVERY RISK';const head2=accepted?'On track for the 18 September required date':risk==='HIGH'?'This order is unlikely to ship on time as planned':risk==='MEDIUM'?'This order needs attention to ship on time':'This order is on track to ship on time';const line=low?'With the recovery plan applied, this order is now on track to meet its required delivery date.':'Without intervention, this order has a significant probability of missing its required delivery date.';return `<div class="verdict ${low?'risk-low-bg':''}" id="tour-risk-score" style="margin-top:14px"><div class="v-num"><div class="big">${prob}%</div><div class="cap">On-Time Probability</div></div><div class="v-main"><span class="v-status">${statusTxt}</span><h2>${head2}</h2><p>${line}</p><div class="v-bar"><i style="width:${prob}%"></i></div><div class="v-scale"><span>0%</span><span>Target 90%</span><span>100%</span></div><div style="margin-top:10px">${howBtn('delivery','How is this calculated?',true)}</div></div></div>`}
function dcTrendChart(){let ctx=document.getElementById('dcTrend');if(!ctx||!window.Chart)return;Chart.getChart(ctx)?.destroy();const labels=['4 wks ago','3 wks','2 wks','Last wk','This wk','Forecast'];new Chart(ctx,{type:'line',data:{labels,datasets:[{label:'On-time %',data:[92.1,91.6,90.8,89.8,88.2,87.8],borderColor:'#0f766e',backgroundColor:'#0f766e18',fill:true,tension:.35,borderWidth:2.5,pointRadius:c=>c.dataIndex>=4?4:2,pointBackgroundColor:c=>c.dataIndex===5?'#bd7a2b':'#0f766e'},{label:'Target 90%',data:Array(6).fill(90),borderColor:'#d1a146',borderDash:[5,4],pointRadius:0,borderWidth:1.2}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:true,labels:{boxWidth:8,font:{size:9}}}},scales:{x:{grid:{display:false},ticks:{font:{size:9}}},y:{min:80,grid:{color:'#eef2f2'},ticks:{font:{size:9},callback:v=>v+'%'}}}}})}
function dcRiskDonut(){let ctx=document.getElementById('dcRisk');if(!ctx||!window.Chart)return;Chart.getChart(ctx)?.destroy();const low=D.orders.filter(o=>o.risk==='LOW').length,med=D.orders.filter(o=>o.risk==='MEDIUM').length,high=D.orders.filter(o=>o.risk==='HIGH').length;new Chart(ctx,{type:'doughnut',data:{labels:['Low risk','Medium risk','High risk'],datasets:[{data:[low,med,high],backgroundColor:['#3f9d8f','#d29a45','#bd5353'],borderWidth:0}]},options:{cutout:'60%',responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{boxWidth:9,font:{size:10},padding:12}},tooltip:{callbacks:{label:c=>`${c.label}: ${c.raw} orders`}}}}})}
function decisionCenter(){
  const high=D.orders.filter(o=>o.risk==='HIGH').length;
  const alertN=(typeof computeAlerts==='function'?computeAlerts().length:5);
  app.innerHTML=head('Decision Center','AI-prioritised decisions requiring management attention','Executive decision centre')
  + `<div class="demo-cta"><span class="dc-badge">● NEW ORDER ARRIVED</span><div class="dc-txt"><b>SO-10482 · Global Fashion Co. · 25,000 units</b><p>A new customer order has entered Oracle ERP. Before committing the delivery date, review the AI verdict, the reasons, and the recommended recovery plan.</p></div><button class="ghost" id="guidedDemo2">▶ Guided walk-through</button><button class="primary" data-page="orders">Review Decision →</button></div>`
  + `<div class="exec-kpis">${dcKpi('Orders at Risk',high,'requiring review','down')}${dcKpi('On-Time Forecast','87.8%','↓ from 91.4% · 30-day','down')}${dcKpi('Capacity This Week','86%','2 lines constrained','')}${dcKpi('AI Alerts',alertN,'across orders, lines & POs','down')}</div>`
  + `<div class="sec-head"><h2>Today’s Priorities</h2><p>The decisions that need management attention right now — ranked by business impact.</p></div>`
  + `<div class="priority-list" id="tour-priorities">${decisionCard('high','1','HIGH','SO-10482 — Delivery Risk','61%','On-time probability','<b>Material shortage</b> (L/XL fabric) + <b>L-07</b> capacity constraint','61% → 91% possible','Review Decision','orders','tour-so-10482')}${decisionCard('med','2','MEDIUM','L-07 — Production Delay Predicted','~14 hrs','Predicted delay','Changeover delay + lower-than-normal hourly output','Recover ~5 hrs','Review Line','production')}${decisionCard('med','3','MEDIUM','PO-48291 — Procurement Anomaly','+20%','Above price range','Unit price above supplier range · unusual quantity',money(42000)+' to review','Investigate','procurement')}</div>`
  + `<div class="sec-head"><h2>Today’s Outlook</h2><p>Where the business is heading — supporting context for the priorities above.</p></div>`
  + `<div class="grid-2"><div class="card panel"><div class="panel-head"><div><h3>On-Time Delivery Trend</h3><p>Recent weeks and the 30-day forecast.</p></div>${howBtn('forecast','How?')}</div><div class="chart-wrap" style="height:220px"><canvas id="dcTrend"></canvas></div></div><div class="card panel"><div class="panel-head"><div><h3>Orders by Risk</h3><p>Across ${D.orders.length} active orders.</p></div></div><div class="chart-wrap" style="height:200px"><canvas id="dcRisk"></canvas></div></div></div>`
  + `<div class="grid-2" style="grid-template-columns:minmax(0,1.3fr) minmax(260px,1fr)"><div class="card panel"><div class="panel-head"><div><h3>AI Daily Brief</h3><p>Today’s management position</p></div><span class="chip risk-med">3 ISSUES</span></div><p style="font-size:12.5px;color:#3d4f54;line-height:1.6;margin:0 0 10px"><b>Good morning.</b> Operations are generally stable, but three issues need attention today.</p><div class="timeline"><div><time>🔴</time><b>SO-10482</b> — 61% on-time probability</div><div><time>🟠</time><b>L-07</b> — ~14 production hours at risk</div><div><time>🟠</time><b>PO-48291</b> — priced above supplier range</div><div><time>🟢</time><b>On-time forecast</b> holding at 87.8%</div></div><div class="button-row"><button class="primary" data-page="orders">Review Priorities</button><button class="secondary" data-page="advisor">Ask AI Assistant</button></div></div><div class="card panel"><div class="panel-head"><div><h3>AI-Assisted Business Impact</h3><p>This month · estimated</p></div></div><div class="impact-strip" id="tour-business-impact" style="grid-template-columns:repeat(2,1fr)"><div class="imp"><div class="iv">4</div><div class="il">Late orders prevented</div></div><div class="imp"><div class="iv">126 hrs</div><div class="il">Production hours recovered</div></div><div class="imp"><div class="iv">18,400</div><div class="il">Units of capacity identified</div></div><div class="imp"><div class="iv">PKR 2.2B</div><div class="il">Procurement value reviewed</div></div></div><p class="notice" style="margin-top:12px">Estimated, AI-assisted figures — baselined during the Proof of Value.</p></div></div>`;
  bindCommon();
  document.getElementById('guidedDemo2')?.addEventListener('click',()=>guidedDemo());
  dcTrendChart(); dcRiskDonut();
}
function acceptOrder(prob){orderState.accepted=true;orderState.prob=prob||91;if(window.Feedback)Feedback.capture({type:'Order commitment',ref:'SO-10482',detail:`${orderState.prob}% on-time · recovery plan`,decision:'Accepted (recovery plan)'});acceptOrderModal(orderState.prob);document.getElementById('navAtRisk')&&(document.getElementById('navAtRisk').textContent='2')}
function acceptOrderModal(prob){prob=prob||orderState.prob;const ts=new Date().toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});document.getElementById('modal').innerHTML=`<div class="modal-content"><button class="close">×</button><span class="label">Human decision · human-in-the-loop</span><h2 style="margin:4px 0 6px" id="tour-decision-recorded">✓ Decision Recorded</h2><p style="color:#3d4f54;font-size:12.5px;margin:0 0 14px">SO-10482 has been <b>accepted</b> for production with the recovery plan activated. The AI advised; you decided.</p><div class="kv"><dt>Decision</dt><dd>Accept order</dd><dt>Decided by</dt><dd>Fahad I. (Executive)</dd><dt>Timestamp</dt><dd>${ts}</dd><dt>Expected on-time</dt><dd>${prob}% · LOW risk</dd><dt>Scenario selected</dt><dd>Reallocate L-03 + limited overtime + expedite material</dd><dt>AI recommendation</dt><dd>Followed</dd></div><div class="interpret">This decision and its outcome are stored as a governed, labelled example for future model learning. <b>The AI does not accept orders automatically — a person does.</b></div><div class="button-row"><button class="primary" id="trackNow">Track Order →</button><button class="secondary" id="closeAccept">Close</button></div></div>`;openModal();document.querySelector('#modal .close').onclick=closeModal;document.getElementById('closeAccept').onclick=closeModal;document.getElementById('trackNow').onclick=()=>{closeModal();render('journey')}}
function holdOrder(){const ts=new Date().toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});if(window.Feedback)Feedback.capture({type:'Order commitment',ref:'SO-10482',detail:'61% on-time · awaiting intervention',decision:'Held for review'});document.getElementById('modal').innerHTML=`<div class="modal-content"><button class="close">×</button><span class="label">Human decision · human-in-the-loop</span><h2 style="margin:4px 0 6px">⏸ Held for Review</h2><p style="color:#3d4f54;font-size:12.5px;margin:0 0 14px">SO-10482 has been <b>held</b> pending review — no delivery date is committed yet. The AI advised; you chose to wait.</p><div class="kv"><dt>Decision</dt><dd>Hold for review</dd><dt>Decided by</dt><dd>Fahad I. (Executive)</dd><dt>Timestamp</dt><dd>${ts}</dd><dt>Current probability</dt><dd>61% · HIGH risk</dd><dt>Routed to</dt><dd>Operations Manager</dd></div><div class="interpret">Recorded to the governed decision log. The order stays at 61% until an intervention is approved.</div><div class="button-row"><button class="primary" id="reviewScenario">Review recovery plan</button><button class="secondary" id="closeHold">Close</button></div></div>`;openModal();document.querySelector('#modal .close').onclick=closeModal;document.getElementById('closeHold').onclick=closeModal;document.getElementById('reviewScenario').onclick=()=>{closeModal();render('scenarios')}}
function orderJourney(){
  const accepted=orderState.accepted;
  const stages=[['Received','done','26 Aug'],['Materials','done','ETA 12 Sep'],['Cutting','done','74% cut'],['Sewing','now','in progress'],['Finishing','wait',''],['Packing','wait',''],['Dispatched','wait','18 Sep']];
  app.innerHTML=head('Order Journey — SO-10482','Where the order is right now, tracked automatically from Barcode, JACK and RFID','Execution & monitoring')
  + (accepted?'':`<div class="notice" style="display:block;margin-bottom:14px">This order has not been accepted yet. Open the <a href="#" data-page="orders" style="color:#0d5f58;font-weight:700">Order Decision</a> to review and accept it — the journey below is illustrative until then.</div>`)
  + orderStripHTML()
  + `<div class="card panel" style="margin-top:14px"><div class="panel-head"><div><h3>Production journey</h3><p>Received → Materials → Cutting → Sewing → Finishing → Packing → Dispatched</p></div><span class="src-chip jack">BARCODE · JACK · RFID</span></div>
      <div class="otrack" id="tour-order-tracking">${stages.map(s=>`<div class="ot-stage ${s[1]}"><div class="ot-dot">${s[1]==='done'?'✓':s[1]==='now'?'●':'○'}</div><b>${s[0]}</b><small>${s[2]}</small></div>`).join('')}</div>
      <div class="ot-detail"><div style="font:700 13px Manrope;display:flex;align-items:center;gap:8px;flex-wrap:wrap">Current stage · Sewing ${statusTag('MEDIUM','Slightly behind plan')}</div>
        <div class="odt-grid"><div><div class="l">Progress</div><div class="v">43%</div></div><div><div class="l">Planned</div><div class="v">48%</div></div><div><div class="l">Variance</div><div class="v" style="color:var(--red)">−5%</div></div><div><div class="l">Sewing lines</div><div class="v">L-07 / L-03</div></div><div><div class="l">Predicted completion</div><div class="v">${accepted?'17 Sep':'21 Sep'}</div></div><div><div class="l">Required</div><div class="v">18 Sep</div></div></div>
        <div class="button-row"><button class="primary" data-page="production">View Production Detail →</button></div></div></div>`
  + `<div class="card panel" id="tour-production-alert" style="margin-top:14px;border-left:4px solid var(--amber)"><div class="panel-head"><div><h3>🟠 Production alert — detected while tracking</h3><p>L-07 (part of this order's sewing split) is starting to slip — early warning, while there is still time to act.</p></div><span class="stag med">🟠 Needs Attention</span></div>
      <p style="font-size:12.5px;color:#3d4f54;line-height:1.55;margin:0 0 6px">L-07 is predicting a <b>~14h delay</b> from changeover and throughput decline. The AI recommends moving <b>800 units to L-03</b> to recover ~5h and protect the 18 Sep date.</p>
      <div class="button-row"><button class="primary" id="jrnL07">Review AI recommendation</button><button class="secondary" data-page="production">Open Production</button></div></div>`
  + `<div class="card panel" style="margin-top:14px"><div class="panel-head"><div><h3>Shop-floor events</h3><p>Automatic status updates from Barcode, JACK and RFID into Oracle.</p></div></div>${critPathHTML()}</div>`;
  bindCommon();
  document.getElementById('jrnL07')?.addEventListener('click',()=>lineDetailModal(D.lines.find(l=>l.id==='L-07')));
}
const pages={decision:decisionCenter,overview:decisionCenter,orders:orderModule,journey:orderJourney,production:productionModule,capacity:capacityModule,procurement:procurementModule,advisor:managementModule,management:managementModule,data:dataPage,aiml:aimlPage,knowledge:knowledgePage,governance,mlops:learningPage,glossary,scenarios:()=>{app.innerHTML=scenarioHTML();bindCommon();bindScenario()},alerts,roi:businessValuePage,risk:orderModule,forecast:orderModule,models:aimlPage,ml:aimlPage,forecasting:aimlPage,anomaly:aimlPage,optimisation:aimlPage,learning:learningPage,fit:dataPage,architecture};
function closeNav(){document.getElementById('sidebar').classList.remove('open');document.getElementById('navScrim').classList.remove('show')}
function render(page){pages[page]?.();document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));closeNav();window.scrollTo({top:0,behavior:'smooth'})}
document.getElementById('mainNav').addEventListener('click',e=>{let b=e.target.closest('[data-page]');if(b)render(b.dataset.page)});document.querySelectorAll('.floating-ai,.advisor-launch').forEach(b=>b.onclick=()=>render('advisor'));document.getElementById('menuBtn').onclick=()=>{document.getElementById('sidebar').classList.toggle('open');document.getElementById('navScrim').classList.toggle('show')};document.getElementById('navScrim').onclick=closeNav;document.getElementById('notifyBtn').onclick=()=>toast('6 notifications: high-risk order, production delay, capacity bottleneck and more.');document.getElementById('userProfile').onclick=()=>{document.getElementById('modal').innerHTML=`<div class="modal-content"><button class="close">×</button><span class="label">DEMO PROFILE</span><h2>Fahad I.</h2><p>Executive access · Shahkam Industries</p><div class="button-row"><button class="primary" data-page="governance">View access &amp; governance</button><button class="secondary" data-page="advisor">Open AI Advisor</button></div></div>`;openModal();document.querySelector('.close').onclick=closeModal;document.querySelectorAll('#modal [data-page]').forEach(b=>b.onclick=()=>{closeModal();render(b.dataset.page)})};document.getElementById('globalSearch').oninput=e=>{let q=e.target.value.toLowerCase(),r=document.getElementById('searchResults');if(q.length<2){r.classList.remove('show');return}let items=[...D.orders,...D.lines.map(l=>({id:l.id,customer:'Production line'})),...D.procurement.slice(0,15).map(p=>({id:p.po,customer:p.supplier}))].filter(x=>(x.id+x.customer).toLowerCase().includes(q)).slice(0,6);r.innerHTML=items.map(x=>`<button data-find="${x.id}"><b>${x.id}</b> <small>— ${x.customer}</small></button>`).join('')||'<button>No matching demo records</button>';r.classList.add('show');r.querySelectorAll('[data-find]').forEach(b=>b.onclick=()=>{r.classList.remove('show');e.target.value='';render(b.dataset.find.startsWith('PO')?'procurement':b.dataset.find.startsWith('L-')?'production':'orders')})};document.addEventListener('click',event=>{let button=event.target.closest('button');if(!button||button.dataset.page||button.dataset.q||button.dataset.chart||button.dataset.flow||button.dataset.find||button.dataset.alertFilter||button.id||button.classList.contains('close'))return;let text=button.textContent.trim().toLowerCase();if(/material|predicted delivery/.test(text))render('orders');else if(/backlog|throughput/.test(text))render('production');else if(/capacity/.test(text))render('capacity');else if(/no matching/.test(text))toast('Try searching an order ID, production line, customer, or PO number.');else toast(`${button.textContent.trim()} selected.`)});document.getElementById('modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});render('decision');
